import { prepareRequestHeaders } from "../utils/headers.js";
import { http } from "../utils/http.js";
const pssEndpoint = 'pss';
/**
 * Sends a message with the Postal Service for Swarm through the `POST /pss/send` endpoint.
 */
export async function send(requestOptions, batchId, topic, target, data, recipient) {
  await http(requestOptions, {
    method: 'post',
    url: `${pssEndpoint}/send/${topic}/${target}`,
    data,
    responseType: 'json',
    params: {
      recipient
    },
    headers: prepareRequestHeaders(batchId)
  });
}